    bars = []

    # Find horizontal bars and fill their internal gaps.
    for r, row in enumerate(grid):
        for color in set(row) - {0}:
            cols = [c for c, v in enumerate(row) if v == color]
            if len(cols) >= 2:
                lo, hi = min(cols), max(cols)
                gaps = [c for c in range(lo, hi + 1) if row[c] == 0]
                bars.append((r, color, gaps))
                for c in range(lo, hi + 1):
                    out[r][c] = color

    # Each bar's gap column carries that bar's color upward, down to the
    # previous horizontal bar. This partitions the vertical space into bands.
    for i, (r, color, gaps) in enumerate(bars):
        previous = max((br for br, _, _ in bars if br < r), default=-1)
        for c in gaps:
            for rr in range(previous + 1, r):
                if grid[rr][c] == 0:
                    out[rr][c] = color

    # Extend existing vertical marker lines through the bottom region.
    for c in range(w):
        colors = [grid[r][c] for r in range(h) if grid[r][c] != 0]
        if not colors:
            continue
        # Vertical marker cells are repeated cells in a column.
        for color in set(colors):
            rows = [r for r in range(h) if grid[r][c] == color]
            if len(rows) >= 2 and max(rows) >= h - 3:
                for rr in range(max(rows) + 1, h):
                    if grid[rr][c] == 0:
                        out[rr][c] = color
    return out
